import React, { useState } from 'react';
import { View, Text, TextInput, Button, StyleSheet } from 'react-native';
import api from '../services/api';

export default function LoginScreen({ onSuccess, onBack }){
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [err, setErr] = useState('');

  const handleLogin = async () => {
    setErr('');
    try {
      const res = await api.post('/auth/login', { correo: email.trim().toLowerCase(), password });
      const data = res.data || {};
      onSuccess && onSuccess(data.usuario || { email: email.trim().toLowerCase() });
    } catch (e) {
      setErr('Error al iniciar sesión');
      console.error(e);
    }
  };

  return (
    <View style={styles.container}>
      <Text style={styles.title}>Iniciar sesión</Text>
      {err ? <Text style={{ color: 'red' }}>{err}</Text> : null}
      <TextInput placeholder="correo@ejemplo.com" value={email} onChangeText={(t) => setEmail(t.toLowerCase())} style={styles.input} keyboardType="email-address" autoCapitalize="none" />
      <TextInput placeholder="Contraseña" value={password} onChangeText={setPassword} style={styles.input} secureTextEntry />
      <View style={{ marginTop: 10 }}>
        <Button title="Entrar" onPress={handleLogin} />
      </View>
      <View style={{ marginTop: 10 }}>
        <Button title="Volver" onPress={onBack} />
      </View>
    </View>
  );
}

const styles = StyleSheet.create({
  container: { flex: 1, padding: 20, justifyContent: 'center' },
  title: { fontSize: 22, fontWeight: '700', marginBottom: 12 },
  input: { borderWidth: 1, borderColor: '#ddd', padding: 10, borderRadius: 8, marginTop: 8 }
});
